Q: How to cleanly make a function which takes any combination of optional parameters in C++? A: <p>Could use <code>std::optional</code> for the parameters.  And <code>{}</code> for the defaulted parameter positions.</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;optional&gt;
#include &lt;string&gt;

using std::cout;
using std::optional;
using std::string;

namespace {

void Function(
    optional&lt;string&gt; s1 = {},
    optional&lt;int&gt; i2 = {},
    optional&lt;string&gt; s3 = {},
    optional&lt;int&gt; i4 = {}
) {
    if (!s1) s1 = &quot;default&quot;;
    if (!i2) i2 = 0;
    if (!s3) s3 = &quot;default&quot;;
    if (!i4) i4 = 0;

    cout &lt;&lt; *s1 &lt;&lt; &quot;\n&quot;
        &lt;&lt; *i2 &lt;&lt; &quot;\n&quot;
        &lt;&lt; *s3 &lt;&lt; &quot;\n&quot;
        &lt;&lt; *i4 &lt;&lt; &quot;\n\n&quot;;
}

}

int main() {
    Function(
        {},
        {},
        &quot;case 1&quot;,
        1
    );

    Function(
        &quot;case 2&quot;,
        2,
        {},
        {}
    );
}
</code></pre>
